body.script:
(function () {
  const usernameInput = document.getElementById('username');
  const refreshBtn = document.getElementById('refreshBtn');
  const statusEl = document.getElementById('status');
  const timestampEl = document.getElementById('timestamp');
  const barcodeEl = document.getElementById('barcode');

  const els = {
    stars: document.getElementById('v-stars'),
    commits: document.getElementById('v-commits'),
    prs: document.getElementById('v-prs'),
    issues: document.getElementById('v-issues'),
    contribs: document.getElementById('v-contribs'),
    total: document.getElementById('v-total'),
  };

  // decorative barcode, fixed pattern so there's no layout jitter
  const widths = [3,1,2,4,1,1,3,2,1,4,2,1,1,3,1,2,4,1,2,1,3,1,1,2,4,1,3,1,2,1];
  barcodeEl.innerHTML = widths.map(w =>
    ``
  ).join('');

  async function restoreUsername() {
    try {
      const res = await window.storage.get('gh-username');
      if (res && res.value) usernameInput.value = res.value;
    } catch (e) { /* no saved username yet, keep default */ }
  }

  function setStatus(text, isError) {
    statusEl.textContent = text;
    statusEl.classList.toggle('error', !!isError);
  }

  function stampTime() {
    const now = new Date();
    timestampEl.textContent = 'issued ' + now.toLocaleDateString() + ' ' + now.toLocaleTimeString();
  }

  async function safeJson(url) {
    const res = await fetch(url, { headers: { Accept: 'application/vnd.github+json' } });
    if (!res.ok) throw new Error(res.status === 404 ? 'not-found' : 'http-' + res.status);
    return res.json();
  }

  async function loadStats() {
    const username = usernameInput.value.trim();
    if (!username) { setStatus('enter a github username', true); return; }

    refreshBtn.disabled = true;
    setStatus('printing…');
    [els.stars, els.commits, els.prs, els.issues, els.contribs, els.total].forEach(el => el.textContent = '–');

    try { await window.storage.set('gh-username', username); } catch (e) { /* storage optional */ }

    const results = await Promise.allSettled([
      safeJson(`https://api.github.com/users/${username}/repos?per_page=100`),
      safeJson(`https://api.github.com/users/${username}/events/public?per_page=100`),
      safeJson(`https://api.github.com/search/issues?q=author:${username}+type:pr`),
      safeJson(`https://api.github.com/search/issues?q=author:${username}+type:issue`),
    ]);

    const [reposR, eventsR, prsR, issuesR] = results;
    let anySuccess = false;
    let total = 0;

    if (reposR.status === 'fulfilled') {
      const stars = reposR.value.reduce((sum, r) => sum + (r.stargazers_count || 0), 0);
      els.stars.textContent = stars;
      total += stars;
      anySuccess = true;
    }

    if (eventsR.status === 'fulfilled') {
      const pushEvents = eventsR.value.filter(e => e.type === 'PushEvent');
      const commits = pushEvents.reduce((sum, e) => sum + ((e.payload && e.payload.commits) ? e.payload.commits.length : 0), 0);
      const contributedRepos = new Set(
        pushEvents
          .filter(e => e.repo && e.repo.name && !e.repo.name.toLowerCase().startsWith(username.toLowerCase() + '/'))
          .map(e => e.repo.name)
      );
      els.commits.textContent = commits;
      els.contribs.textContent = contributedRepos.size;
      total += commits + contributedRepos.size;
      anySuccess = true;
    }

    if (prsR.status === 'fulfilled') {
      els.prs.textContent = prsR.value.total_count;
      total += prsR.value.total_count;
      anySuccess = true;
    }

    if (issuesR.status === 'fulfilled') {
      els.issues.textContent = issuesR.value.total_count;
      total += issuesR.value.total_count;
      anySuccess = true;
    }

    els.total.textContent = anySuccess ? total : '–';
    stampTime();

    if (!anySuccess) {
      setStatus('live fetch unavailable here — save the file and open it in a browser to see real numbers.', true);
    } else if (reposR.status === 'rejected' && reposR.reason && reposR.reason.message === 'not-found') {
      setStatus('user not found — check the username.', true);
    } else if (results.some(r => r.status === 'rejected')) {
      setStatus('partial data — some GitHub requests were rate-limited or blocked.', true);
    } else {
      setStatus('commits update automatically as you push — hit refresh anytime.');
    }

    refreshBtn.disabled = false;
  }

  refreshBtn.addEventListener('click', loadStats);
  usernameInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') loadStats(); });

  restoreUsername().then(loadStats);
  setInterval(loadStats, 5 * 60 * 1000);
})();
